# ----------------------------------------------------------------------
# 2️⃣  Custom CUDA kernel for depth‑wise 2D convolution (asymmetric, square kernel)
# ----------------------------------------------------------------------
elementwise_conv_cpp_source = "torch::Tensor depthwise_conv_cuda(torch::Tensor input, torch::Tensor kernel);"
elementwise_conv_cuda_source = """
__global__ void depthwise_conv_kernel(const float* input, const float* kernel,
                                       float* output, int batch_size, int in_channels,
                                       int H_in, int W_in, int stride, int padding,
                                       int dilation, int k_h, int k_w, int out_h, int out_w) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * in_channels * out_h * out_w) {
        // unpack linear index
        int total_elements_per_block = batch_size * in_channels * out_h * out_w;
        int b   = idx / (in_channels * out_h * out_w);
        int rem = idx % (in_channels * out_h * out_w);
        int c   = rem / (out_h * out_w);
        rem    = rem % (out_h * out_w);
        int oh  = rem / out_w;
        int ow  = rem % out_w;

        // input start coordinates
        int in_h_start = oh * stride + padding - k_h/2;
        int in_w_start = ow * stride + padding - k_w/2;

        float sum = 0.0f;
        for (int ch = 0; ch < in_channels; ++ch) {
            for (int kp = 0; kp < k_h; ++kp) {
                int ih = in_h_start + kp;
                if (ih >= H_in || ih < 0) continue;
                for (int kq = 0; kq < k_w; ++kq) {
                    int iw = in_w_start + kq;
                    if (iw >= W_in || iw < 0) continue;
                    float a_val = input[b * in_channels * H_in * W_in + ch * H_in * W_in + ih * W_in + iw];
                    float k_val  = kernel[ch * k_h * k_w + kp * k_w + kq];
                    sum += a_val * k_val;
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor depthwise_conv_cuda(torch::Tensor input, torch::Tensor kernel) {
    auto batch_size   = input.size(0);
    auto in_channels  = input.size(1);
    auto H_in         = input.size(2);
    auto W_in         = input.size(3);

    int k_h = kernel.size(0);          # first dimension of kernel (channels)
    int k_w = kernel.size(2);          # second dimension (kernel width)

    // output spatial size
    int out_h = (H_in + 2*padding - k_h) / stride + 1;
    int out_w = (W_in + 2*padding - k_w) / stride + 1;

    auto output_shape = torch.Size({batch_size, in_channels, out_h, out_w});
    auto output       = torch::zeros(output_shape);

    // flatten pointers
    auto input_ptr   = input.data_ptr<float>();
    auto kernel_ptr  = kernel.data_ptr<float>();

    int total_out_elements = batch_size * in_channels * out_h * out_w;
    const int threads_per_block = 256;
    int num_blocks = (total_out_elements + threads_per_block - 1) / threads_per_block;

    depthwise_conv_kernel<<<num_blocks, threads_per_block>>>(
        input_ptr, kernel_ptr, output.data_ptr<float>(),
        batch_size, in_channels, H_in, W_in, stride, padding,
        dilation, k_h, k_w, out_h, out_w
    );

    return output;
}
"""

# Compile the inline CUDA code for depth‑wise convolution
elementwise_conv = load_inline(
    name="depthwise_conv",
    cpp_sources=elementwise_conv_cpp_source,
    cuda_sources=elementwise_conv_cuda_source,
